"use client";

import * as React from "react";
import { memo, useMemo, useState, useCallback } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { cn } from "../../../../lib/utils";
import {
  formatValue,
  calculateNiceTicks,
  getGridDasharray,
  useContainerDimensions,
  ChartTooltip,
} from "../_shared";
import type { ChartDataItem, WaterfallChartTooltipData, TooltipRenderer } from "../_shared";
import { computeWaterfallSeries, formatWaterfallDelta } from "./utils";
import type { WaterfallBar } from "./utils";

interface WaterfallColors {
  readonly increase?: string;
  readonly decrease?: string;
  readonly total?: string;
}

interface WaterfallChartProps<T extends ChartDataItem> {
  readonly data: readonly T[];
  /** Key holding each step's label. Defaults to `"label"`. */
  readonly x?: keyof T;
  /** Key holding each step's numeric value. Defaults to `"value"`. */
  readonly y?: keyof T;
  /** Key holding each step's type (`"increase" | "decrease" | "total"`). Defaults to `"type"`; inferred from sign when absent. */
  readonly type?: keyof T;
  readonly colors?: WaterfallColors;
  readonly className?: string;
  readonly height?: number;
  readonly loading?: boolean;
  readonly error?: string | null;
  readonly animation?: boolean;
  readonly orientation?: "vertical" | "horizontal";
  /** Draw the connector lines that link each step's running total to the next. Defaults to `true`. */
  readonly showConnectors?: boolean;
  /** Render the signed delta / total on each bar. Defaults to `false`. */
  readonly showValues?: boolean;
  readonly showGrid?: boolean;
  readonly gridStyle?: "solid" | "dashed" | "dotted";
  /** Show the increase/decrease/total legend. Defaults to `false`. */
  readonly showLegend?: boolean;
  readonly onBarClick?: (data: T, index: number) => void;
  readonly tooltipRenderer?: TooltipRenderer<WaterfallChartTooltipData<T>>;
}

// Constants
const DEFAULT_COLORS: Required<WaterfallColors> = {
  increase: "#10b981",
  decrease: "#ef4444",
  total: "#3b82f6",
};

const DEFAULT_HEIGHT = 300;
const MARGIN = { top: 24, right: 24, bottom: 40, left: 56 };
const ANIMATION_EASING = [0.4, 0, 0.2, 1] as const;
const HOVER_DURATION = 0.2;
const LEGEND_HEIGHT = 28;

// Approximate horizontal character width at a given font size (SVG text has no
// auto-ellipsis), used to trim category labels so they never collide/overflow.
function truncateLabel(label: string, maxPx: number, fontSize = 11): string {
  const charPx = fontSize * 0.62;
  const maxChars = Math.floor(maxPx / charPx);
  if (label.length <= maxChars) return label;
  if (maxChars <= 1) return "…";
  return `${label.slice(0, maxChars - 1).trimEnd()}…`;
}

// Loading/Error/Empty States
function LoadingState({ height = DEFAULT_HEIGHT }: { height?: number }) {
  // Floating bars staggered off a baseline to evoke a waterfall's staircase.
  const bars = [
    { h: 46, offset: 0 },
    { h: 16, offset: 44 },
    { h: 13, offset: 58 },
    { h: 15, offset: 46 },
    { h: 20, offset: 30 },
    { h: 52, offset: 0 },
  ];
  return (
    <div className="relative w-full" style={{ height }}>
      <div className="absolute inset-0 flex flex-col p-4">
        <div className="animate-pulse motion-reduce:animate-none bg-muted rounded h-3.5 w-24 mb-4 shrink-0" />
        <div className="relative flex-1 flex items-end gap-2 sm:gap-3 border-l border-b border-muted/25 pl-2">
          {bars.map((bar, i) => (
            <div key={i} className="flex-1 flex flex-col justify-end h-full">
              <div
                className="w-full rounded-sm bg-muted/70 animate-pulse motion-reduce:animate-none"
                style={{
                  height: `${bar.h}%`,
                  marginBottom: `${bar.offset}%`,
                  animationDelay: `${i * 0.12}s`,
                }}
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function ErrorState({ error }: { error: string }) {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-destructive font-medium">Chart Error</div>
        <div className="text-sm text-muted-foreground">{error}</div>
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-muted-foreground">No Data</div>
        <div className="text-sm text-muted-foreground">
          There&apos;s no data to display
        </div>
      </div>
    </div>
  );
}

function Legend({ colors }: { colors: Required<WaterfallColors> }) {
  const items = [
    { label: "Increase", color: colors.increase },
    { label: "Decrease", color: colors.decrease },
    { label: "Total", color: colors.total },
  ] as const;
  return (
    <div className="flex items-center justify-center gap-4 mt-3">
      {items.map((item) => (
        <div key={item.label} className="flex items-center gap-1.5">
          <span
            className="inline-block w-2.5 h-2.5 rounded-sm"
            style={{ backgroundColor: item.color }}
          />
          <span className="text-xs text-muted-foreground">{item.label}</span>
        </div>
      ))}
    </div>
  );
}

// Main Component
function WaterfallChartComponent<T extends ChartDataItem>({
  data,
  x = "label" as keyof T,
  y = "value" as keyof T,
  type = "type" as keyof T,
  colors,
  className,
  height = DEFAULT_HEIGHT,
  loading = false,
  error = null,
  animation = true,
  orientation = "vertical",
  showConnectors = true,
  showValues = false,
  showGrid = false,
  gridStyle = "dashed",
  showLegend = false,
  onBarClick,
  tooltipRenderer,
}: WaterfallChartProps<T>) {
  const [containerRef, containerWidth] = useContainerDimensions();
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  const reduceMotion = useReducedMotion();
  const shouldAnimate = animation && !reduceMotion;

  const palette = useMemo<Required<WaterfallColors>>(
    () => ({ ...DEFAULT_COLORS, ...colors }),
    [colors]
  );

  const isVertical = orientation === "vertical";
  const chartWidth = Math.max(0, containerWidth - MARGIN.left - MARGIN.right);
  // Reserve room for the legend so it stays inside the fixed-height root.
  const svgHeight = showLegend ? Math.max(0, height - LEGEND_HEIGHT) : height;
  const chartHeight = svgHeight - MARGIN.top - MARGIN.bottom;

  // Dev warning for large datasets
  if (process.env.NODE_ENV === "development" && data.length > 50) {
    // eslint-disable-next-line no-console
    console.warn(
      `[WaterfallChart] ${data.length} data points detected. Waterfall charts read best with a small number of steps.`
    );
  }

  const series = useMemo(
    () => computeWaterfallSeries(data, { label: x, value: y, type }),
    [data, x, y, type]
  );

  const ticks = useMemo(() => {
    const { min, max } = series.domain;
    if (min === max) return [min];
    return calculateNiceTicks(min, max, 5);
  }, [series.domain]);

  const scale = useMemo(() => {
    const min = Math.min(series.domain.min, ...ticks);
    const max = Math.max(series.domain.max, ...ticks);
    const span = max - min || 1;
    return { min, max, span };
  }, [series.domain, ticks]);

  const gridDasharray = useMemo(() => getGridDasharray(gridStyle), [gridStyle]);

  // Map a value to a pixel position along the value axis (px from plot origin).
  const valueToPixel = useCallback(
    (value: number) => {
      const ratio = (value - scale.min) / scale.span;
      return isVertical ? chartHeight - ratio * chartHeight : ratio * chartWidth;
    },
    [scale, isVertical, chartHeight, chartWidth]
  );

  const bars = useMemo(() => {
    if (!series.bars.length || chartWidth <= 0 || chartHeight <= 0) return [];

    const count = series.bars.length;
    const slot = (isVertical ? chartWidth : chartHeight) / count;
    const thickness = slot * 0.68;
    const pad = (slot - thickness) / 2;

    return series.bars.map((bar) => {
      const cross = bar.index * slot + pad; // position along the category axis
      const lowPx = valueToPixel(bar.displayStart);
      const highPx = valueToPixel(bar.displayEnd);
      const color = palette[bar.type];

      // In vertical mode higher value → smaller y, so the "high" edge is the top (min y).
      const rect = isVertical
        ? { x: cross, y: Math.min(lowPx, highPx), width: thickness, height: Math.abs(lowPx - highPx) }
        : { x: Math.min(lowPx, highPx), y: cross, width: Math.abs(lowPx - highPx), height: thickness };

      return { bar, color, cross, thickness, rect };
    });
  }, [series.bars, chartWidth, chartHeight, isVertical, valueToPixel, palette]);

  const zeroPixel = useMemo(() => valueToPixel(0), [valueToPixel]);

  // Event handlers
  const handleMouseEnter = useCallback((index: number) => setHoveredIndex(index), []);
  const handleMouseLeave = useCallback(() => setHoveredIndex(null), []);
  const handleClick = useCallback(
    (barData: T, index: number) => onBarClick?.(barData, index),
    [onBarClick]
  );
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, barData: T, index: number) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        onBarClick?.(barData, index);
      }
    },
    [onBarClick]
  );

  if (loading) return <LoadingState height={height} />;
  if (error) return <ErrorState error={error} />;
  if (!data.length) return <EmptyState />;

  if (!containerWidth) {
    return (
      <div ref={containerRef} className={cn("relative w-full", className)} style={{ height }}>
        <div className="flex items-center justify-center h-full text-sm text-muted-foreground">
          Loading...
        </div>
      </div>
    );
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)} style={{ height }}>
      <svg
        width="100%"
        height={svgHeight}
        className="overflow-visible"
        role="group"
        aria-label={`Waterfall chart with ${data.length} steps in ${orientation} orientation`}
      >
        <g transform={`translate(${MARGIN.left}, ${MARGIN.top})`}>
          {/* Value grid lines */}
          {showGrid &&
            ticks.map((tick, i) => {
              const p = valueToPixel(tick);
              return isVertical ? (
                <line
                  key={`grid-${i}`}
                  x1={0}
                  y1={p}
                  x2={chartWidth}
                  y2={p}
                  stroke="currentColor"
                  opacity={0.1}
                  strokeDasharray={gridDasharray}
                />
              ) : (
                <line
                  key={`grid-${i}`}
                  x1={p}
                  y1={0}
                  x2={p}
                  y2={chartHeight}
                  stroke="currentColor"
                  opacity={0.1}
                  strokeDasharray={gridDasharray}
                />
              );
            })}

          {/* Value-axis ticks + labels */}
          {ticks.map((tick, i) => {
            const p = valueToPixel(tick);
            return isVertical ? (
              <g key={`tick-${i}`}>
                <line x1={-4} y1={p} x2={0} y2={p} stroke="currentColor" opacity={0.3} />
                <text
                  x={-8}
                  y={p}
                  textAnchor="end"
                  dominantBaseline="middle"
                  fontSize={11}
                  className="fill-muted-foreground"
                >
                  {formatValue(tick)}
                </text>
              </g>
            ) : (
              <g key={`tick-${i}`}>
                <line x1={p} y1={chartHeight} x2={p} y2={chartHeight + 4} stroke="currentColor" opacity={0.3} />
                <text
                  x={p}
                  y={chartHeight + 16}
                  textAnchor="middle"
                  fontSize={11}
                  className="fill-muted-foreground"
                >
                  {formatValue(tick)}
                </text>
              </g>
            );
          })}

          {/* Baseline (value = 0) */}
          {isVertical ? (
            <line x1={0} y1={zeroPixel} x2={chartWidth} y2={zeroPixel} stroke="currentColor" opacity={0.35} strokeWidth={1.5} />
          ) : (
            <line x1={zeroPixel} y1={0} x2={zeroPixel} y2={chartHeight} stroke="currentColor" opacity={0.35} strokeWidth={1.5} />
          )}

          {/* Connector lines between consecutive steps */}
          {showConnectors &&
            bars.map((b, i) => {
              if (i === bars.length - 1) return null;
              const next = bars[i + 1];
              if (!next) return null;
              const level = valueToPixel(b.bar.cumulative);
              return isVertical ? (
                <line
                  key={`conn-${i}`}
                  x1={b.rect.x + b.thickness}
                  y1={level}
                  x2={next.rect.x}
                  y2={level}
                  stroke="currentColor"
                  opacity={0.35}
                  strokeWidth={1}
                  strokeDasharray="2 2"
                />
              ) : (
                <line
                  key={`conn-${i}`}
                  x1={level}
                  y1={b.rect.y + b.thickness}
                  x2={level}
                  y2={next.rect.y}
                  stroke="currentColor"
                  opacity={0.35}
                  strokeWidth={1}
                  strokeDasharray="2 2"
                />
              );
            })}

          {/* Bars */}
          {bars.map(({ bar, color, rect }) => {
            const isHovered = hoveredIndex === bar.index;
            // Grow each bar from its start edge (the previous running total), so the
            // waterfall builds step by step. transform-box: fill-box makes the
            // percentage origin resolve against the bar's own box.
            const growFromLowEdge = bar.start === bar.displayStart;
            const transformOrigin = isVertical
              ? growFromLowEdge
                ? "50% 100%"
                : "50% 0%"
              : growFromLowEdge
                ? "0% 50%"
                : "100% 50%";

            const motionProps = shouldAnimate
              ? {
                  initial: isVertical ? { scaleY: 0 } : { scaleX: 0 },
                  animate: isVertical ? { scaleY: 1 } : { scaleX: 1 },
                  transition: { duration: 0.6, delay: bar.index * 0.06, ease: ANIMATION_EASING },
                }
              : {};

            const deltaLabel = formatWaterfallDelta(bar, formatValue);
            const a11yLabel = `${bar.label}: ${bar.type}, ${deltaLabel}, running total ${formatValue(bar.cumulative)}`;

            return (
              <g key={bar.index}>
                <motion.rect
                  x={rect.x}
                  y={rect.y}
                  width={rect.width}
                  height={Math.max(rect.height, 1)}
                  fill={color}
                  rx={3}
                  className="cursor-pointer touch-manipulation focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  style={{
                    transformBox: "fill-box",
                    transformOrigin,
                    filter: isHovered && !reduceMotion ? `drop-shadow(0 0 6px ${color})` : "none",
                    transition: reduceMotion ? "none" : `filter ${HOVER_DURATION}s ease-out`,
                  }}
                  {...motionProps}
                  tabIndex={0}
                  role="graphics-symbol"
                  aria-label={a11yLabel}
                  onMouseEnter={() => handleMouseEnter(bar.index)}
                  onMouseLeave={handleMouseLeave}
                  onFocus={() => handleMouseEnter(bar.index)}
                  onBlur={handleMouseLeave}
                  onClick={() => handleClick(bar.data, bar.index)}
                  onKeyDown={(e: React.KeyboardEvent) => handleKeyDown(e, bar.data, bar.index)}
                />

                {/* Value label on the bar */}
                {showValues &&
                  (isVertical ? (
                    <text
                      x={rect.x + rect.width / 2}
                      y={rect.y - 6}
                      textAnchor="middle"
                      fontSize={11}
                      className="fill-foreground font-medium select-none pointer-events-none"
                    >
                      {deltaLabel}
                    </text>
                  ) : (
                    <text
                      x={rect.x + rect.width + 6}
                      y={rect.y + rect.height / 2}
                      textAnchor="start"
                      dominantBaseline="middle"
                      fontSize={11}
                      className="fill-foreground font-medium select-none pointer-events-none"
                    >
                      {deltaLabel}
                    </text>
                  ))}
              </g>
            );
          })}

          {/* Category labels (truncated to the space available so they never collide/overflow) */}
          {bars.map(({ bar, cross, thickness }) => {
            const slotSize = thickness / 0.68;
            const label = isVertical
              ? truncateLabel(bar.label, slotSize - 2)
              : truncateLabel(bar.label, MARGIN.left - 12);
            const truncated = label !== bar.label;
            return (
              <g key={`cat-${bar.index}`}>
                {isVertical ? (
                  <text
                    x={cross + thickness / 2}
                    y={chartHeight + 16}
                    textAnchor="middle"
                    fontSize={11}
                    className="fill-muted-foreground"
                  >
                    {truncated && <title>{bar.label}</title>}
                    {label}
                  </text>
                ) : (
                  <text
                    x={-8}
                    y={cross + thickness / 2}
                    textAnchor="end"
                    dominantBaseline="middle"
                    fontSize={11}
                    className="fill-muted-foreground"
                  >
                    {truncated && <title>{bar.label}</title>}
                    {label}
                  </text>
                )}
              </g>
            );
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {(() => {
        const hovered = hoveredIndex !== null ? bars[hoveredIndex] : null;
        if (!hovered) {
          return <ChartTooltip visible={false} x={0} y={0}>{null}</ChartTooltip>;
        }
        const { bar, color, rect } = hovered;
        const tipData: WaterfallChartTooltipData<T> = {
          label: bar.label,
          type: bar.type,
          value: bar.value,
          cumulative: bar.cumulative,
          color,
          index: bar.index,
          data: bar.data,
        };

        const tooltipPos = isVertical
          ? {
              left: rect.x + rect.width / 2 + MARGIN.left,
              top: Math.max(10, rect.y + MARGIN.top - 12),
            }
          : {
              left: rect.x + rect.width + MARGIN.left + 10,
              top: rect.y + rect.height / 2 + MARGIN.top,
            };

        return (
          <ChartTooltip
            visible
            x={tooltipPos.left}
            y={tooltipPos.top}
            className={isVertical ? "transform -translate-x-1/2 -translate-y-full" : "transform -translate-y-1/2"}
          >
            {tooltipRenderer ? (
              tooltipRenderer(tipData)
            ) : (
              <>
                <div className="flex items-center gap-2 mb-1">
                  <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: color }} />
                  <span className="text-xs font-medium text-foreground whitespace-nowrap">
                    {bar.label}
                  </span>
                </div>
                <div className="text-sm font-bold text-primary tabular-nums text-center">
                  {formatWaterfallDelta(bar, formatValue)}
                </div>
                <div className="text-[11px] text-muted-foreground tabular-nums text-center mt-0.5">
                  Total: {formatValue(bar.cumulative)}
                </div>
              </>
            )}
          </ChartTooltip>
        );
      })()}

      {showLegend && <Legend colors={palette} />}
    </div>
  );
}

// Cast preserves the generic call signature that memo() would otherwise erase,
// so consumers keep typed `data`, `onBarClick`, and `tooltipRenderer`.
export const WaterfallChart = memo(WaterfallChartComponent) as typeof WaterfallChartComponent;
export type { WaterfallChartProps, WaterfallColors };
export type { WaterfallBar, WaterfallType } from "./utils";
export { DEFAULT_COLORS };

import { getNumericValue } from "../_shared";
import type { ChartDataItem } from "../_shared";

export type WaterfallType = "increase" | "decrease" | "total";

/**
 * A single resolved waterfall bar in value-space (not yet mapped to pixels).
 *
 * `start`/`end` are the running total before/after this step. For "total" bars
 * the bar is anchored to the baseline (start = 0). `displayStart`/`displayEnd`
 * are the low/high edges of the floating bar, ready for a value→pixel scale.
 */
export interface WaterfallBar<T extends ChartDataItem> {
  readonly data: T;
  readonly index: number;
  readonly label: string;
  readonly type: WaterfallType;
  /** Signed delta for increase/decrease bars; the absolute value for totals. */
  readonly value: number;
  /** Running total before this step (value-space). */
  readonly start: number;
  /** Running total after this step (value-space); equals `cumulative`. */
  readonly end: number;
  /** Low edge of the floating bar: min(start, end). */
  readonly displayStart: number;
  /** High edge of the floating bar: max(start, end). */
  readonly displayEnd: number;
  /** Running total after this step (alias of `end`, used by connectors/tooltip). */
  readonly cumulative: number;
}

export interface WaterfallSeries<T extends ChartDataItem> {
  readonly bars: readonly WaterfallBar<T>[];
  /** Value-space domain that always includes 0 (the baseline). */
  readonly domain: { readonly min: number; readonly max: number };
}

/**
 * Resolve the bar type. An explicit `"increase" | "decrease" | "total"` wins;
 * otherwise the type is inferred from the sign of the value (negative →
 * decrease, non-negative → increase).
 */
export function resolveWaterfallType(rawType: unknown, value: number): WaterfallType {
  if (rawType === "total" || rawType === "increase" || rawType === "decrease") {
    return rawType;
  }
  return value < 0 ? "decrease" : "increase";
}

/**
 * Turn raw data rows into cumulative waterfall bars.
 *
 * - `total` bars assert an absolute baseline: they draw from 0 to their value
 *   and reset the running total to that value.
 * - `increase`/`decrease` bars float from the current running total by their
 *   (sign-normalised) magnitude.
 */
export function computeWaterfallSeries<T extends ChartDataItem>(
  data: readonly T[],
  keys: { readonly label: keyof T; readonly value: keyof T; readonly type: PropertyKey }
): WaterfallSeries<T> {
  let running = 0;
  let min = 0;
  let max = 0;

  const bars = data.map((item, index): WaterfallBar<T> => {
    const rawValue = getNumericValue(item as ChartDataItem, keys.value as string);
    const type = resolveWaterfallType((item as ChartDataItem)[keys.type as string], rawValue);

    let start: number;
    let end: number;
    let value: number;

    if (type === "total") {
      value = rawValue;
      start = 0;
      end = rawValue;
      running = rawValue;
    } else if (type === "increase") {
      value = Math.abs(rawValue);
      start = running;
      end = running + value;
      running = end;
    } else {
      value = -Math.abs(rawValue);
      start = running;
      end = running + value;
      running = end;
    }

    const displayStart = Math.min(start, end);
    const displayEnd = Math.max(start, end);
    min = Math.min(min, displayStart);
    max = Math.max(max, displayEnd);

    return {
      data: item,
      index,
      label: String(item[keys.label] ?? ""),
      type,
      value,
      start,
      end,
      displayStart,
      displayEnd,
      cumulative: end,
    };
  });

  return { bars, domain: { min, max } };
}

/**
 * Format the delta shown on a bar: totals show their absolute value, while
 * increases/decreases carry an explicit sign (e.g. `+45.0K`, `-12.0K`).
 */
export function formatWaterfallDelta(
  bar: Pick<WaterfallBar<ChartDataItem>, "type" | "value">,
  format: (value: unknown) => string
): string {
  if (bar.type === "total") return format(bar.value);
  return bar.value > 0 ? `+${format(bar.value)}` : format(bar.value);
}
